int dx[4] = {-1, 1, 0, 0};
int dy[4] = {0, 0, -1, 1};

// 【核心蜕变】：办事大厅直接提拔为全局变量！
queue&lt;pair&lt;int, int&gt;&gt; q; 

// ================= 纯粹的干活机器 =================
// 连参数 sx, sy 都不需要了！它就是一个无情的叫号机
void bfs() 
{
    while (q.size() &gt; 0) 
    {
        auto t = q.front(); 
        q.pop(); 

        int x = t.first;
        int y = t.second;

        // 如果题目需要单点出口，就在这里加 if(x == ex &amp;&amp; y == ey) return;
        // 如果是全图蔓延，就不写出口，随它去。

        for (int i = 0; i &lt; 4; ++i) 
        {
            int nx = x + dx[i];
            int ny = y + dy[i];

            if (nx &lt; 1 || nx &gt; n || ny &lt; 1 || ny &gt; m) continue; 
            // if (g[nx][ny] == &#039;#&#039;) continue;  // 撞墙安检（视题目而定）
            if (dist[nx][ny] != -1) continue;                   

