【状压 BFS (字符串流派)】模板
#include &lt;bits/stdc++.h&gt;
using namespace std;

// ================= 1. 全局变量区 (状态空间三件套) =================
unordered_map&lt;string, int&gt; dist; // 查库存钢印本：记录每张“照片”出现的最短步数
queue&lt;string&gt; q;                 // 办事大厅：存的是“照片”
int ans = -1;                    // 全局大喇叭
string tar = &quot; ...&quot;;             // 🎯 目标照片 (记得最前面加空格占位！)

// 物理方向盘 (视题目变异规则而定)
int dx[5] = {0, 1, 0, -1, 0};
int dy[5] = {0, 0, 1, 0, -1};
int N = 3; // 矩阵的宽度 (如 3x3 则为 3)

// ================= 2. 幕后翻译机 (极其关键的解耦) =================
// 作用：把一维字符串照片，洗成你最熟悉的二维画板
void stom(string s, int g[10][10]) 
{
    // i 的上限看题目总共有几个格子
    for(int i = 1; i &lt;= N * N; ++i) 
    {
        int r = (i - 1) / N + 1;
        int c = (i - 1) % N + 1;
        g[r][c] = s[i] - &#039;0&#039;; // 字符转数字
    }
}

// 作用：把二维画板上的废墟，重新拍成一张一维字符串照片
string mtos(int g[10][10]) 
{
    string s = &quot; &quot;; // 灵魂空格：维持万物从 1 开始！
    for(int i = 1; i &lt;= N * N; ++i) 
    {
        int r = (i - 1) / N + 1;
        int c = (i - 1) % N + 1;
        s += to_string(g[r][c]); // 数字转字符拼上去
    }
    return s;
}

// ================= 3. 纯血无参干活机器 =================
void bfs()
{
    while(q.size() &gt; 0)
    {
        string x = q.front();
        q.pop();

        // 🎯 1. 单点出口：长相跟目标一模一样，下班！
        if(x == tar)
        {
            ans = dist[x];
            return ;
        }

        // 🎯 2. 核心分支：枚举所有的【操作】 (比如按 9 个开关，或者移动空格)
        for(int i = 1; i &lt;= N * N; ++i)
        {
            // --- 阶段 A：拿原片复印，准备作案 ---
            int g[10][10];
            stom(x, g); // 自动复印成二维矩阵，随便炸，不影响原字符串 x

            int r = (i - 1) / N + 1;
            int c = (i - 1) % N + 1;

            // --- 阶段 B：实施物理变异 (因题目而异) ---
            for(int j = 0; j &lt; 5; ++j)
            {
                int nx = r + dx[j];
                int ny = c + dy[j]; 

                // 物理越界拦截
                if(nx &lt; 1 || nx &gt; N || ny &lt; 1 || ny &gt; N) continue;

                g[nx][ny] = 1 - g[nx][ny]; // 变异规则 (开灯题是翻转，八数码题是 swap 交换)
            }

            // --- 阶段 C：将作案现场拍成新照片 ---
            string ne_x = mtos(g);

            // ============ 安检门 (一贯的 continue 风格) ============
            if(dist.count(ne_x) != 0) continue; // 查库存：哈希表里有了，说明别人走过

            // ============ 进门盖章 ============
            dist[ne_x] = dist[x] + 1; 
            q.push(ne_x);
        }
    }
}

// ================= 4. 调度室 =================
int main()
{
    ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);

    // 开局拼接带空格的照片
    string sta_s = &quot; &quot;;
    for(int i = 1; i &lt;= N * N; ++i)
    {
        char c;
        cin &gt;&gt; c;
        sta_s += c; 
    } 

    // 起点入队
    q.push(sta_s);
    dist[sta_s] = 0;

    bfs();
    cout &lt;&lt; ans &lt;&lt; &#039;\n&#039;;

    return 0;
}
P1443 马的遍历
题目描述
有一个 n \times m 的棋盘，在某个点 (x, y) 上有一个马，要求你计算出马到达棋盘上任意一个点最少要走几步。
输入格式
输入只有一行四个整数，分别为 n, m, x, y。
输出格式
一个 n \times m 的矩阵，代表马到达某个点最少要走几步（不能到达则输出 -1）。
输入输出样例 #1
输入 #1
3 3 1 1


输出 #1
0 3 2    
3 -1 1    
2 1 4    

说明/提示
数据规模与约定
对于全部的测试点，保证 1 \leq x \leq n \leq 400，1 \leq y \leq m \leq 400。
2022 年 8 月之后，本题去除了对输出保留场宽的要求。为了与之兼容，本题的输出以空格或者合理的场宽分割每个整数都将判作正确。
#include &lt;bits/stdc++.h&gt;
using namespace std;
using ll = long long;
const int N = 410;
int dist[N][N];
