int n,m;
int dx[5] = {0,1,0,-1,0};
int dy[5] = {0,0,1,0,-1};
int dist[N][N];
char g[N][N]; //char

void bfs()
{
	while(q.size() &gt; 0)
	{
		auto t = q.front();
		q.pop();
		int x = t.first;
		int y = t.second;

		for(int i = 1;i &lt;= 4;++i)
		{
			int nx = x+dx[i];
			int ny = y+dy[i];

			if(nx &lt; 1 || nx &gt; n || ny &lt; 1 || ny &gt; m) continue;
			if(dist[nx][ny] != -1) continue;

			dist[nx][ny] = dist[x][y] + 1;
			q.push({nx,ny}); 

		}


	}

}


int main()
{
