#include &lt;bits/stdc++.h&gt;
using namespace std;
using ll = long long;
unordered_map&lt;string,int&gt; dist;
queue &lt;string&gt; q;
int ans = -1;
string tar = &quot; 111111111&quot;;//留空 s从一开始 
int dx[5] = {0,1,0,-1,0};
int dy[5] = {0,0,1,0,-1};//这里是余波 不是门 包括自己 0有效哦 

void stom(string s,int g[4][4])
{
	for(int i = 1;i &lt;= 9;++i)
	{
		int r = (i-1) / 3 + 1;
		int c = (i-1) % 3 + 1;
		g[r][c] = s[i] - &#039;0&#039;;

	 } 
}
string mtos(int g[4][4])
{
	string s = &quot; &quot;;
	for(int i = 1;i &lt;= 9;++i)
	{
		int r = (i-1) / 3 + 1;
		int c = (i-1) % 3 + 1;
		s += to_string(g[r][c]);// 数字变字符直接拼 ； 
	}
	return s;
}

void bfs()
{
	while(q.size() &gt; 0)
	{
		auto t = q.front();
		q.pop();
