		if(x == tar)
		{
			ans = dist[x];
			return ;
		}

		for(int i = 1;i &lt;= 9;++i) //这个才是移动 
		{
			int g[4][4];
			stom(x,g); //转换成矩阵坐标 方便 变换； 
			int r = (i-1) / 3 + 1;
			int c = (i-1) % 3 + 1;//算二维矩阵坐标，相当于 x,y 

			for(int j = 0;j &lt; 5;++j)//这个是算余波 不是方向 
			{
				int nx = r + dx[j];
				int ny = c + dy[j]; 
				if(nx &lt; 1 || nx &gt; 3 || ny &lt; 1 || ny &gt; 3) continue;
				g[nx][ny] = 1 - g[nx][ny];//翻转 

			}

			string ne_x = mtos(g) ;
			if(dist.count(ne_x) != 0) continue;//是否重复 安检 

			dist[ne_x] = dist[x] + 1; 
			q.push(ne_x);




		}

	}


}


