char ch[3] = {&#039;#&#039;, &#039;O&#039;, &#039;X&#039;};

// 参数说明：
// step: 当前在填第几个坑
// rev: 挡位指令（0 代表前进挡，1 代表倒车挡）
void dfs(int step, int rev) {
    // 【安检门 1：成功出口】
    if (step &gt; n) {
        for (int i = 1; i &lt;= n; i++) {
            cout &lt;&lt; ch[st[i]]; // 输出当前合法状态（注意题目是否要求空格）
        }
        cout &lt;&lt; &#039;\n&#039;;
        return;
    }

    // 【核心分支：根据挡位决定出牌顺序】
    if (rev == 0) { 
        // 🚗 收到前进指令 (rev == 0)：顺序出牌 1 -&gt; 2

        // 分支 1：出 1。因为是第一条路，给小弟传 0（前进）
        st[step] = 1;
        dfs(step + 1, 0); 

        // 分支 2：出 2。因为是第二条路（最后一步），给小弟传 1（倒车）
        st[step] = 2;
        dfs(step + 1, 1); 
    } 
    else {          
        // 🚜 收到倒车指令 (rev == 1)：逆序出牌 2 -&gt; 1

        // 分支 1：出 2。因为是第一条路，给小弟传 0（前进）
        st[step] = 2;
        dfs(step + 1, 0); 

        // 分支 2：出 1。因为是第二条路（最后一步），给小弟传 1（倒车）
        st[step] = 1;
        dfs(step + 1, 1); 
    }
}

