数独填数(排列型)
数独 DFS 的本质，就是前期用数组记录目标，后期套用全排列模板暴力试错(注意特别检验合法不)。
#include &lt;iostream&gt;
#include &lt;cstdlib&gt; // exit(0) 强制下班必备
using namespace std;

const int K = 2; // K 是小包厢的边长。如果题目是 2x2 宫格，K=2；如果是 9x9 经典数独，K=3！
const int MAX_SIZE = K * K; // 整个棋盘的边长

int grid[20][20]; // 物理棋盘

// 坑位名单（降维打击的核心）
int px[100], py[100]; 
int pit_cnt = 0; // 记录总共有几个坑

// 🛡️ 专门查验在 (x, y) 放入数字 val 合不合法
bool check(int x, int y, int val) {
    // 1. 查十字线（同行、同列）
    for (int i = 1; i &lt;= MAX_SIZE; i++) {
        if (grid[x][i] == val) return false; 
        if (grid[i][y] == val) return false; 
    }

    // 2. 查小包厢：精准定位左上角
    int startX = ((x - 1) / K) * K;
    int startY = ((y - 1) / K) * K;

    for (int i = 0; i &lt; K; i++) {
        for (int j = 0; j &lt; K; j++) {
            if (grid[startX + i][startY + j] == val) {
                return false; // 拦截！
            }
        }
    }
    return true; // 放行！
}

// 🐕 DFS 狗：专门根据名单填坑
// 参数 step: 当前在填名单上的第几个坑
void dfs(int step) {
    // 【成功出口】
    if (step &gt; pit_cnt) {
        // 打印整个修补好的二维棋盘
        for (int i = 1; i &lt;= MAX_SIZE; i++) {
            for (int j = 1; j &lt;= MAX_SIZE; j++) {
                cout &lt;&lt; grid[i][j] &lt;&lt; &quot; &quot;;
            }
            cout &lt;&lt; &#039;\n&#039;;
        }
        exit(0); // 只要一个答案？拿到直接下班！
    }

    // 拿出名单，看看当前要填的坑在真实棋盘的哪个坐标
    int x = px[step];
    int y = py[step];

    // 【核心分支：每种萝卜都试一遍】
    for (int i = 1; i &lt;= MAX_SIZE; i++) {

        // 【安检门 2：苛刻的保安查验】
        if (!check(x, y, i)) continue; // 冲突了，直接扔掉这个萝卜试下一个

        // 【打钢印】：坑里填入萝卜
        grid[x][y] = i;

        // 【传参 dfs】：踏向下一个坑
        dfs(step + 1);

        // 【擦钢印 / 毁尸灭迹】：排列型必须还原现场！
        grid[x][y] = 0; 
    }
}

int main() {
    // 读入数据阶段，提前“收集坑位” 就是把你最怕的“二维棋盘满屏幕乱找”，强行【降维打击】成了你闭着眼睛都能写的“一维单排填坑（排列型）
    for (int i = 1; i &lt;= MAX_SIZE; i++) {
        for (int j = 1; j &lt;= MAX_SIZE; j++) {
            cin &gt;&gt; grid[i][j];
            if (grid[i][j] == 0) {
                pit_cnt++;
                px[pit_cnt] = i;
                py[pit_cnt] = j;
            }
        }
    }

    // 放狗！从名单上的第 1 个坑开始填！
    dfs(1);

    return 0;
}
