#include &lt;bits/stdc++.h&gt;
using namespace std;
using ll = long long;
const int N = 100;
ll ans;
int n,k;
ll a[N];
bool is_prime(int x)
{
	if(x &lt; 2) return false;
	if(x == 2) return true;
	if(x % 2 == 0) return false ;
	for(int i = 3;i * i &lt;= x;i+=2)
	{
		if(x % i == 0) return false;
	}
	return true;
}

void dfs(int x,ll sum,int sta)
{
	if(x &gt; k)
	{
		if(is_prime(sum)) ans++;

		return ;
	 } 
	for(int i = sta;i &lt;= n-k+x;++i)
	{

		dfs(x+1,sum+a[i],i+1);
	}



}

int main()
{
	ios::sync_with_stdio(0);cin.tie(0);cout.tie(0);
	cin &gt;&gt; n &gt;&gt; k;
	for(int i = 1;i &lt;= n;++i) cin &gt;&gt; a[i];
	dfs(1,0,1);
	cout &lt;&lt; ans &lt;&lt;&#039;\n&#039;;

	return 0;
}
