由于你是黄蓉的朋友，她事先告诉你哪些砖是安全的、哪些砖是不安全的，并且她会指引你飞到第一块砖上（第一块砖可能在任意安全位置），现在她告诉你进入桃花岛的秘密就是：如果你能走过最多的瓷砖并且没有死，那么桃花岛的大门就会自动打开了，你就可以从当前位置直接飞进大门了。
注意：瓷砖可以重复走过，但不能重复计数。
输入格式
第一行两个正整数 W 和 H，分别表示小路的宽度和长度。
以下 H 行为一个 H\times W 的字符矩阵。每一个字符代表一块瓷砖。其中，. 代表安全的砖，# 代表不安全的砖，@ 代表第一块砖。
输出格式
输出一行，只包括一个数，即你从第一块砖开始所能安全走过的最多的砖块个数（包括第一块砖）。
输入输出样例 #1
输入 #1
11 9
.#.........
.#.#######.
.#.#.....#.
.#.#.###.#.
.#.#..@#.#.
.#.#####.#.
.#.......#.
.#########.
...........


输出 #1
59

说明/提示
数据规模与约定
对于全部的测试点，保证 1 \leq W,H\le 20。
#include &lt;bits/stdc++.h&gt; 
using namespace std;
const int N = 29;
int w,h;
char a[N][N];//要读字符，类型char，不要无脑int
bool st[N][N];
int dx[5] = {0,-1,0,1,0};
int dy[5] = {0,0,1,0,-1};
int cnt;
int sta_x,sta_y;

void dfs(int x,int y)
{
	if(x &lt; 1 || x &gt; h || y &lt; 1 || y &gt; w) return ; //不要x,y写错了；
	if(a[x][y] == &#039;#&#039;) return ;
	if(st[x][y] == true) return;

	cnt++;
	st[x][y] = true; //没终点 不需要 return;

	for(int i =1;i&lt;=4;++i) 
	{
		int nx = x + dx[i];
		int ny = y + dy[i];
		dfs(nx,ny);
	} //方向数组；


}

int main()
{
	cin &gt;&gt; w &gt;&gt; h;
	for(int i = 1;i &lt;= h;++i)
	{
		for(int j = 1;j &lt;= w;++j) 
		{
			cin &gt;&gt; a[i][j];
		}
	}

	for(int i = 1;i &lt;= h;++i)
	{
		for(int j = 1;j &lt;= w;++j) 
		{
			if(a[i][j] == &#039;@&#039;) sta_x = i,sta_y = j; //寻找初始点；
		}
	}

	dfs(sta_x,sta_y);

	cout &lt;&lt; cnt &lt;&lt;&#039;\n&#039;;


	return 0;
}
