#include &lt;bits/stdc++.h&gt;
using namespace std;
using ll = long long;
const int N = 19;
int cnt[N];
ll n;
ll m_gcd = -1;
ll ans = 2e9;

ll gcd(ll a,ll b) //有ll就统一用保平安 
{
	return b == 0 ? a : gcd(b,a%b);//本质每轮除数与被除数互换，所以b,a%b; 
}

void dfs(int x,ll v,int stcnt)//ll v ,保平安； 
{
	if(x &gt; 9)//是位数，生成数的位数，造字符串的感觉 
	{
		ll c_gcd = gcd(v,n);
		if(c_gcd &gt; m_gcd)
		{
			m_gcd = c_gcd;
			ans = v;// 当满足最小的最大公约数时候，记录单号为答案； 
		}

		return ;
	}

	for(int i = 1;i&lt;=8;++i)
	{
		if(cnt[i] == 2) continue;
		if(cnt[i] == 1 &amp;&amp; stcnt == 1) continue;
		cnt[i]++;
		dfs(x+1,v*10+i,stcnt + (cnt[i] == 2 ? 1 : 0));
		cnt[i]--;
	}

}

int main()
{
	if(cin &gt;&gt; n)
	{
		dfs(1,0,0) ;
		cout &lt;&lt; ans &lt;&lt;&#039;\n&#039;;
	}

	return 0;
}
