#include &lt;bits/stdc++.h&gt;
using namespace std;
int n;
const int N = 25;
string a[N];
int st[N];
char ch[N] ={&#039;#&#039;,&#039;O&#039;,&#039;X&#039;};
void dfs(int x,int res)
{
	if(x &gt; n)
	{
		for(int i =1;i &lt;=n;++i)
		{
			if(st[i])
			{
				cout &lt;&lt; ch[st[i]];
			}
		}
		cout &lt;&lt; &#039;\n&#039;;
		return ;
	}
	if (res == 0) // 🚗 收到前进指令 (rev == 0)：顺序出牌 1 -&gt; 2

        // 分支 1：出 1。因为是第一条路，给小弟传 0（前进）
	{
		st[x] = 1;
		dfs(x+1,0);
		st[x] = 2;
		dfs(x+1,1);
	}
	else  // 🚜 收到倒车指令 (rev == 1)：逆序出牌 2 -&gt; 1

