			for(int j = 1;j &lt;= m;++j)
			{
				if(M[i][j] == &#039;*&#039; &amp;&amp; !st[i][j])
				{
					msize = 0;//计算多块中某一块连通块数量要清空记录，如果不， 到了另一块连通块就会重复累加， 
					dfs(i,j);
					bkt[msize]++; 

				} 
			}	
		}
		int ans = 0;
		for(int i = 1;i &lt; N*N;++i) // i 为sz 
		{
			if(bkt[i] &gt; 0)
			{
				ans ++;
				maxsize = max(maxsize,i * bkt[i]);//求最大值打擂台 
			}


		}
		cout &lt;&lt; ans &lt;&lt; &#039; &#039; &lt;&lt; maxsize &lt;&lt;&#039;\n&#039;;

	}


 return 0;	
} 
