题目描述
千秋正在玩一种数字游戏，这种数字游戏需要在一个 4\times 4 的网格内填数，每个方格内填入一个 1\sim 4 范围内的整数。
游戏胜利当且仅当下面的条件被全部满足：

将网格划分为 4 个 2\times 2 的子网格，每个子网格中不存在重复的数
网格的每行不存在重复的数
网格的每列不存在重复的数

子网格的划分如图所示。

千秋已经填好了其中的若干个数，请你完成剩余的数，使得游戏胜利。可能存在多种符合要求的填法，你只需要给出其中一种即可。
输入格式
输入四行，每行四个数，表示网格已经填入的数。
未填入的位置用 0 表示。
保证已经填入的位置均符合游戏胜利的要求。
输出格式
输出 4 行，每行 4 个整数。表示完成后的游戏局面。
输入输出样例 #1
输入 #1
3 0 4 1
4 1 2 0
1 0 3 2
2 3 1 0

输出 #1
3 2 4 1
4 1 2 3
1 4 3 2
2 3 1 4

说明/提示
用 n 表示未填的格子数目。
对于 5\% 的测试数据，n=1。
对于另外 25\% 的测试数据，n=4 且恰好有一行未填。
对于另外 30\% 的测试数据，n=7 且恰好有一行一列未填。
对于 100\% 的测试数据，1 \le n \le 16，已经填好的数不违反游戏胜利的要求，保证存在符合游戏胜利的解。
#include&lt;bits/stdc++.h&gt;
using namespace std;
const int K = 2;
const int N = K * K + 9;

int M[N][N];
int px[N*N],py[N*N];
int p_cnt;
bool check(int x,int y,int v)
{
	for(int i = 1;i &lt;= K*K;++i)
	{
		if(M[i][y] == v) return false;
		if(M[x][i] == v) return false;
	}
	int sta_x = ((x-1) / K ) * K;
	int sta_y = ((y-1) / K ) * K;
	for(int i = 1;i&lt;=K;++i)
	{
		for(int j = 1; j&lt;=K;++j)
		{
			if(M[sta_x+i][sta_y+j] == v) return false;
		}
	}
	return true;
}
void dfs(int step)
{
	if(step &gt; p_cnt)
	{
		for(int i = 1;i&lt;=K*K;++i)
		{
			for(int j = 1; j&lt;=K*K;++j)
			{
				cout &lt;&lt; M[i][j] &lt;&lt;&quot; \n&quot;[j==K*K];
			}

		}

		exit(0);
	}

	int x = px[step];
	int y = py[step];
	for(int i = 1; i &lt;= K*K;++i)
	{
		if(!check(x,y,i)) continue;
		M[x][y] = i;
		dfs(step + 1);
		M[x][y] = 0;
	}

}

int main()
{
	for(int i = 1;i&lt;=K*K;++i)
	{
		for(int j = 1; j&lt;=K*K;++j)//注意数独边长是K*K 
		{
			cin &gt;&gt; M[i][j];
			if(M[i][j] == 0)
			{
				p_cnt++;
				px[p_cnt] = i;
				py[p_cnt] = j;

			}
