#include &lt;bits/stdc++.h&gt;
using namespace std;
using ll = long long;
int n,ans;
bool st[1000];
int a[1000];
void dfs(int x,int cnt,int sum,int pic)
{
	if(cnt &gt; n || pic == n)// 翻译题目 数的大于牌最大则结束 
	{						// 牌没了也要结束 
		ans = max(ans,sum);
		return ;
	}

	if(x &gt; n) x = 1;
	if(st[x]) 
	{
		dfs(x+1,cnt,sum,pic);
		return ;
	}

		if(a[x] == cnt)
		{
			st[x] = true;
			dfs(x+1,1,sum+a[x],pic+1);
			st[x] = false;
		}
		else
		{

			dfs(x+1,cnt+1,sum,pic);

		}

}

