浮点二分模版：

✍️答案二分
跳石头
#include &lt;iostream&gt;
#include &lt;bits/stdc++.h&gt;
using namespace std;
int L,N,M;
const int n =5e4+9;
int a[n];
bool check(int mid)
{
  int re = 0,la = 0;
  for(int i = 1;i &lt;= N;i++)
  {
    if(a[i] - a[la] &lt; mid) re++;//太短了，不合法，就不跳过去，增加移除的石头
    else la = i; //合法 跳过去即可


  }
  if (L - a[la] &lt; mid) re++;

  return re &lt;= M;
}

int main()
{
  cin &gt;&gt; L &gt;&gt; N &gt;&gt; M;
  for(int i = 1;i &lt;= N;i++)
  {
    cin &gt;&gt; a[i];
  }
  int l = 0,r = L + 1;
  for(;(l + 1) != r;)
  {
    int mid = (l + r) / 2;
    if(check(mid)) l = mid;
    else r = mid;
  }
  cout &lt;&lt; l &lt;&lt; endl;




  return 0;
}
