// 处理进位；C【i+j+1】 为 前一位十位的累加
// C【i+j】 当前位保留个位
//处理最后一位的进位；当前位加上借位
//倒序遍历输出并且  筛选（为了去除前置0），范围不会超过两乘数的和；
//定义过滤标志flag=ture:假设最后一个（倒过来就是在前面）数一定为0
//如果满足位数大于0，同时标志开启，当前值为0，则continue 直接跳过
//如果 标志开启 同时 当前值不等于0 则 标志关闭 false
//标志过滤关闭的情况下 直接输出

✍️ 标准语法 (Syntax)

#include &lt;iostream&gt;
#include &lt;bits/stdc++.h&gt;
using namespace std;



int main(){

  string a,b;
  cin &gt;&gt; a &gt;&gt; b;
  vector&lt;int&gt; A,B;
  for(int i = a.size()-1;i &gt;= 0;i--)
  {
    A.push_back(a[i] - &#039;0&#039;);
  }

  for(int i = b.size()-1;i &gt;= 0;i--)
  {
    B.push_back(b[i] - &#039;0&#039;);
  }

  vector&lt;int&gt; C(10000);
  for(int i = 0;i &lt; B.size();i++)
  {
    int t = 0;
    int j = 0;
    for(;j &lt; A.size();j++)
    {
      int num = t + (A[j] * B[i]);
      int ret = num % 10;
      t = num / 10;
      C[i+j] += ret;
      C[i+j+1] += C[i+j] / 10;
      C[i+j] = C[i+j] % 10;
    }
    if(t &gt; 0) C[i+j] += t;
  }

  for(int i = A.size() + B.size();i &gt;= 0;i--)
  {
    bool flag = true;
    if(flag &amp;&amp; i &gt; 0 &amp;&amp; C[i] == 0)
    {
      continue;
    }

    if(flag &amp;&amp; C[i] != 0)
    {
      flag = false;
    }
    cout &lt;&lt; C[i];

  }



  return 0;
}

