# include &lt;iostream&gt;
# include &lt;bits/stdc++.h&gt;
using namespace std;
bool is_Max(vector&lt;int&gt; a,vector&lt;int&gt; b)
{
  if (a.size() == b.size()) 
  {
    for(int i = a.size()-1;i &gt;= 0;i--)
    { if(a[i] == b[i]) continue;
      return a[i] &gt; b[i];
    }
  }
  return a.size() &gt; b.size() ;
}


int main(){
string a,b;
cin &gt;&gt; a &gt;&gt; b;
vector&lt;int&gt; A,B;
for(int i = a.size()-1;i &gt;= 0;i--)
{
  A.push_back(a[i] - &#039;0&#039;);
}

for(int i = b.size()-1;i &gt;= 0;i--)
{
  B.push_back(b[i] - &#039;0&#039;);
}
bool flag = false; 
if(!is_Max(A,B))
{
  swap(A,B);
  flag = true;
}
int t = 0;
vector&lt;int&gt; C;
for(int i =0;i &lt; max(A.size(),B.size());i++)
{
  int num = -t;
  if(i &lt; A.size()) num += A[i];

  if(i &lt; B.size()) num -= B[i];
  if(num &lt; 0)
  {
    t = 1;
    C.push_back(num + 10);
  }
  else 
  {
    t = 0;
    C.push_back(num);
  }

}

while (C.size() &gt; 1 &amp;&amp; C.back() == 0)
{
  C.pop_back();
}

if(C.size() == 1 &amp;&amp; C.back() == 0)
{
  cout &lt;&lt; &quot;0&quot; &lt;&lt; endl;
}
if(flag)
{
  cout &lt;&lt; &quot;-&quot;;
}


for(int i = C.size()-1;i &gt;= 0;i--)
{
  cout &lt;&lt; C[i];
}

  return 0;
}

