bool ns(int x)
{
	int step = 0;
	while(x &gt; 0)
	{

		int r1 = x % 10;
		if(step == 0 &amp;&amp; r1 == 3) step++;
		if(step == 1 &amp;&amp; r1 == 2) step++;
		if(step == 2 &amp;&amp; r1 == 0) step++;
		if(step == 3 &amp;&amp; r1 == 2) return true;


		x/=10;
	}

	return false;
}

