bool is_prime(ll x) {
    if (x &lt; 2) return false;
    if (x == 2) return true;
    if (x % 2 == 0) return false; // 偶数直接秒杀
    for (int i = 3; i * i &lt;= x; i += 2) { // 每次 +2，只查奇数 3, 5, 7...
        if (x % i == 0) return false;
    }
    return true;
}
