#include &lt;iostream&gt;
#include &lt;algorithm&gt; // 召唤 max 函数
using namespace std;

// 记忆库存：记录每棵灌木上次被剪是第几天，以及历史最高纪录
// 全局数组默认初始化为 0，完美契合“第 0 天大家都是 0 厘米”的设定
int last_cut[10005]; 
int max_h[10005];

int main() {
    ios::sync_with_stdio(0); cin.tie(0); cout.tie(0);

    int n;
    cin &gt;&gt; n;

    // 特判：如果只有 1 棵灌木，每天都被剪，长不高
    if (n == 1) {
        cout &lt;&lt; 0 &lt;&lt; &#039;\n&#039;;
        return 0;
    }

    int pos = 1; // 记忆：Alice 当前在第 1 棵灌木
    int dir = 1; // 记忆：Alice 面朝右边 (1右，-1左)

    // 我们需要模拟多少天？
    // Alice 走一个来回大概是 2*n 天。
    // 我们模拟 4*n 天（走两三个来回），绝对足够每一棵灌木都达到最高点！
    int total_days = 4 * n; 

    for (int day = 1; day &lt;= total_days; ++day) {

        // 1. 算高度：今天 - 上次被剪的日子 (极其优雅的时间戳减法！)
        int h = day - last_cut[pos];

        // 2. 挑战历史最高记录
        max_h[pos] = max(max_h[pos], h);

        // 3. 一剪刀下去，记录今天剪了它
        last_cut[pos] = day;

        // 4. 准备去明天：先判断是不是该调头了？
        if (pos == n) {
            dir = -1; // 撞到最右边，调头向左
        } else if (pos == 1) {
            dir = 1;  // 撞到最左边，调头向右
        }

        // 5. 往前迈一步
        pos += dir;
    }

    // 模拟结束，盘点所有灌木的最高纪录并输出
    for (int i = 1; i &lt;= n; ++i) {
        cout &lt;&lt; max_h[i] &lt;&lt; &#039;\n&#039;;
    }

    return 0;
}
